'use client';
import {useCallback,useEffect,useId,useMemo,useRef,useState,type FormEvent} from 'react';
import {getSupabaseBrowserClient} from '../../../lib/supabase/browser';
import {EXCLUSION_LABELS,centerPixelLabel,imageDataUrl,METHODS,METHOD_LABELS,MATCH_GRADE_LABELS,matchGrade,percent,REASONS,STATE_LABELS,summarize,tokyo,type Evaluation,type GroundReport,type Health,type ImageRow,type LabData,type Shadow} from '../../../lib/research/rainLab';
import {LabAccessError,loadCaseImages,loadLab,saveGround} from '../../../lib/research/rainLabRepository';
import s from './lab.module.css';
import {explainCase,PATTERNS,VERDICT_LABELS} from '../../../lib/research/rainMismatch';
const jma=(value:string|null)=>{if(!value)return '';if(/^\d{14}$/.test(value))return value;const d=new Date(value);return Number.isFinite(d.getTime())?d.toISOString().replace(/[-:TZ.]/g,'').slice(0,14):'';};
const EVENT_LABELS:Record<string,string>={RAIN_ENDING:'止むよ',RAIN_APPROACHING:'降るよ',ACTIONABLE_RAIN_APPROACHING:'降るよ'};
const FEEDBACK:Record<string,string>={RAINED:'降った',DID_NOT_RAIN:'降らなかった',ALREADY_RAINING:'すでに降っていた',STOPPED:'止んだ',DID_NOT_STOP:'止まなかった',ALREADY_DRY:'すでに降っていなかった',UNKNOWN:'わからない'};
function Crop({image,location,title}:{image:ImageRow|null;location:{latitude:number;longitude:number};title:string}){
 const patternId=useId().replace(/:/g,'');const [dark,setDark]=useState(false);
 const url=image?imageDataUrl(image.crop_png):null,w=image?.metadata.window;
 const worldX=(location.longitude+180)/360*262144,worldY=(1-Math.asinh(Math.tan(location.latitude*Math.PI/180))/Math.PI)/2*262144;
 const masks=image?.availability_mask.slice(2).match(/../g)??[];
 return <figure className={s.figure}><figcaption>{title}</figcaption>{image&&url&&w?<><div className={s.crop} style={dark?{backgroundColor:'#263d50',backgroundImage:'none'}:undefined}>
  {/* Raw PNG pixels, not a resampled weather prediction. */}<img src={url} alt={`${title} ${tokyo(image.valid_time)}の雨量画像`} />
  <svg viewBox={`0 0 ${image.width} ${image.height}`} aria-hidden='true'><defs><pattern id={`missing-${patternId}`} width='0.6' height='0.6' patternUnits='userSpaceOnUse'><path d='M0 0L.6 .6' stroke='#c12d6b' strokeWidth='.12'/></pattern></defs>
   {masks.map((v,i)=>v==='00'?<rect key={i} x={i%image.width} y={Math.floor(i/image.width)} width='1' height='1' fill={`url(#missing-${patternId})`}/>:null)}
   {[250,500,1000].map((r,i)=><circle key={r} cx={worldX-w.originX} cy={worldY-w.originY} r={r/w.metersPerPixel} fill='none' stroke={['#159786','#3476c4','#c58a2a'][i]} strokeWidth='1.2' vectorEffect='non-scaling-stroke'/>)}
   <path d={`M${worldX-w.originX-.6} ${worldY-w.originY}h1.2M${worldX-w.originX} ${worldY-w.originY-.6}v1.2`} stroke='#c63c54' strokeWidth='1.6' vectorEffect='non-scaling-stroke'/>
  </svg></div><button type='button' className={s.contrast} aria-pressed={dark} onClick={()=>setDark(!dark)}>{dark?'市松背景に戻す':'淡い雨色を暗い背景で見る'}</button><div className={s.muted}>対象 {tokyo(image.valid_time)}</div><div className={s.notes}>中心：{centerPixelLabel(image,(Math.floor(worldY)-w.originY)*image.width+Math.floor(worldX)-w.originX)}<br/>RGBA {image.metadata.centerRgba?['r','g','b','a'].map(k=>image.metadata.centerRgba![k as 'r'|'g'|'b'|'a']).join(', '):'未取得'}</div><div className={s.notes}>発表 {tokyo(image.base_time)}<br/>取得 {tokyo(image.metadata.capturedAt)}<br/>{image.complete?'全画素取得':'欠けた画素あり'}{image.frame_kind==='FORECAST'?image.metadata.matchesInputPixel===true?' · 当時の中心と一致':' · 入力中心は未確認':''}</div>{image.frame_kind==='FORECAST'?<p className={s.notes}>同じ発表・対象時刻・地点のURLから後で回収した画像です。中心画素の一致は、通知時の画像全体が同一だった証明にはなりません。当時の画像全体のハッシュは未保存です。</p>:null}</>:<div className={s.noImage}>この時刻の画像は未保存です<br/>保存対象外・未回収を含みます</div>}</figure>;
}
function GroundForm({evaluation,onSaved}:{evaluation:Evaluation;onSaved:()=>Promise<void>}){
 const [weather,setWeather]=useState<GroundReport['weather']|''>(''),[time,setTime]=useState(''),[source,setSource]=useState<GroundReport['report_source']>('AT_LOCATION'),[confirmed,setConfirmed]=useState(false),[note,setNote]=useState(''),[busy,setBusy]=useState(false),[message,setMessage]=useState(''),[success,setSuccess]=useState(false);
 const submit=async(event:FormEvent)=>{event.preventDefault();setSuccess(false);setMessage('');if(!weather||!time){setMessage('天気と実際に確認した時刻を入力してください。');return;}setBusy(true);try{await saveGround(getSupabaseBrowserClient(),{evaluation_id:evaluation.id,observed_at:new Date(time).toISOString(),weather,report_source:source,location_confirmed:confirmed,note});setSuccess(true);setMessage('開発用の観測を保存しました。一般向け履歴の回答は変更していません。');await onSaved();}catch{setMessage('保存できませんでした。確認時刻・地点の確認・閲覧権限を確認してください。');}finally{setBusy(false);}};
 const now=()=>{const d=new Date(),local=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);setTime(local);};
 return <form className={s.form} onSubmit={event=>void submit(event)}><h3>現地の参考情報を記録（任意）</h3><p className={s.muted}>現地にいた場合だけ、確認できた事実を任意で記録してください。入力しなくても自動評価は進みます。近隣情報も参考として保存します。</p>
  <div className={s.formGrid}><label className={s.label}>実際の天気<select value={weather} onChange={e=>setWeather(e.target.value as typeof weather)} required><option value=''>選んでください</option><option value='RAIN'>雨が降っていた</option><option value='NO_RAIN'>雨は降っていなかった</option><option value='UNKNOWN'>確認できない</option></select></label>
   <label className={s.label}>確認方法<select value={source} onChange={e=>{setSource(e.target.value as typeof source);setConfirmed(false);}}><option value='AT_LOCATION'>登録地点そのもので確認</option><option value='CAMERA'>登録地点のカメラで確認</option><option value='NEARBY_REFERENCE'>近隣の情報・雨量計など（参考）</option></select></label>
   <label className={s.label}>実際に確認した時刻<input type='datetime-local' value={time} onChange={e=>setTime(e.target.value)} required/></label><div><button type='button' onClick={now}>いまの時刻を入力</button></div></div>
  {source!=='NEARBY_REFERENCE'?<label className={s.check}><input type='checkbox' checked={confirmed} onChange={e=>setConfirmed(e.target.checked)} required/>登録地点そのものと、入力した時刻の天気を確認しました</label>:<p className={s.notes}>近隣の情報は、登録地点の正解として一致率に使いません。</p>}
  <label className={s.label}>メモ（任意・300文字まで）<textarea maxLength={300} value={note} onChange={e=>setNote(e.target.value)}/></label><p className={s.notes}>同じケース・同じ時刻の再保存は訂正になります。現地報告がない場合や報告同士が食い違う場合でも、レーダーによる自動評価は保留にしません。</p>
  <button disabled={busy} type='submit'>{busy?'保存中…':'開発用の観測を保存'}</button>{message?<p role='status' className={success?s.success:s.error}>{message}</p>:null}</form>;
}
function CaseCard({evaluation,shadow,label,reports,feedback,threshold,onSaved}:{evaluation:Evaluation;shadow:Shadow|undefined;label:string;reports:GroundReport[];feedback:LabData['feedback'][number]|undefined;threshold:number;onSaved:()=>Promise<void>}){
 const [images,setImages]=useState<ImageRow[]|null>(null),[loading,setLoading]=useState(false),[error,setError]=useState(''),[selectedTime,setSelectedTime]=useState(jma(evaluation.target_time)),[base,setBase]=useState(shadow?.comparison.groups[0]?.baseTime??'');const request=useRef(0);
 useEffect(()=>()=>{request.current++;},[]);
 const load=async()=>{const rid=++request.current;setLoading(true);setError('');try{const rows=await loadCaseImages(getSupabaseBrowserClient(),evaluation.id);if(rid===request.current)setImages(rows);}catch{if(rid===request.current)setError('画像を取得できません。権限と接続を確認してください。');}finally{if(rid===request.current)setLoading(false);}};
