 const explanations=explainCase(evaluation,shadow,selectedTime,group?.baseTime,threshold,reports);
 const grade=matchGrade(evaluation);
 const candidates={point:group?.point.series.find(f=>f.validTime===selectedTime),area:variant?.area.series.find(f=>f.validTime===selectedTime),combined:variant?.combined.series.find(f=>f.validTime===selectedTime)};
 return <details className={s.case} onToggle={event=>{if(event.currentTarget.open&&images===null&&!loading)void load();}}><summary><span><strong>{label} · {EVENT_LABELS[evaluation.event_type]??'雨通知'}</strong><br/><span className={s.muted}>{tokyo(evaluation.created_at)} 通知 · 予測対象 {tokyo(evaluation.target_time)}</span></span><span className={`${s.grade} ${s[`grade_${grade}`]}`}>{MATCH_GRADE_LABELS[grade]}</span></summary>
 <div className={s.caseBody}><div className={s.caseOverview}><strong className={`${s.grade} ${s[`grade_${grade}`]}`}>{MATCH_GRADE_LABELS[grade]}</strong><p>{grade==='exact'?'予測した時刻にレーダーの変化が一致しました。':grade==='within5'?'予測時刻から5分以内にレーダーの変化が一致しました。':grade==='within10'?'予測時刻から10分以内にレーダーの変化が一致しました。':grade==='mismatch'?'予測時刻の前後10分まで確認しましたが、レーダーの変化は一致しませんでした。':'必要な実況が不足しているなどの理由で、まだ一致・不一致を決められません。'}</p><div className={s.overviewTimes}><span>通知 <strong>{tokyo(evaluation.created_at)}</strong></span><span>予測した時刻 <strong>{tokyo(evaluation.target_time)}</strong></span></div><p className={s.notes}>※これはレーダーとの比較で、現地の雨を証明するものではありません。</p></div><p>{evaluation.snapshot.body}</p><span className={s.tag}>実況 {evaluation.state==='PENDING'?'回収中':evaluation.state==='COMPLETE'?'照合済み':'一部確認できず'}</span><span className={s.tag}>画像 {evaluation.image_state==='COMPLETE'?'保存済み':evaluation.image_state==='PENDING'?'回収中':'一部未取得'}</span>
 <details className={s.technical}><summary>処理状況・回収回数などの詳細</summary><div className={s.notes}>処理回数：実況 {evaluation.attempts??'—'} / 画像 {evaluation.image_attempts??'—'} / 比較 {evaluation.shadow_attempts??'—'}（初回を含むclaim回数）<br/>実況締切 {tokyo(evaluation.deadline_at)} · 画像は締切＋10分または60回、比較は締切＋20分または24回が通常処理の終了目安です。例外が続く場合や容量制限時の停止は別途監査が必要です。<br/>実況で未回収の時刻：{evaluation.radar_result?.missingTimes?.length?evaluation.radar_result.missingTimes.map(tokyo).join('、'):'なし／まだ未集計'}{evaluation.last_error||evaluation.image_error||evaluation.shadow_error?<><br/>取得・処理エラーあり。正常終了の記録とは分けて確認してください。</>:null}</div></details>
 <div className={s.filters}><label className={s.label}>比較する時刻<select value={selectedTime} onChange={e=>setSelectedTime(e.target.value)}>{times.map(t=><option key={t} value={t}>{tokyo(t)}</option>)}</select></label>{(shadow?.comparison.groups.length??0)>1?<label className={s.label}>予測の発表時刻<select value={group?.baseTime} onChange={e=>setBase(e.target.value)}>{shadow?.comparison.groups.map(g=><option key={g.baseTime} value={g.baseTime}>{tokyo(g.baseTime)}</option>)}</select></label>:null}<button type='button' disabled={loading} onClick={()=>void load()}>{loading?'画像を読込中…':'画像を更新'}</button></div>
 {error?<p className={s.error}>{error}</p>:null}<div className={s.images}><Crop image={forecast} location={evaluation.snapshot.location} title='当時の予測（後から回収）'/><Crop image={observation} location={evaluation.snapshot.location} title='対象時刻の実況'/></div>
 <p className={s.notes}>左が通知時点の予測、右が予測対象時刻の実況です。＋は登録地点、円は周辺250m・500m・1kmを表します。</p><div className={s.legend}><span style={{color:'#159786'}}>○ 250m</span><span style={{color:'#3476c4'}}>○ 500m</span><span style={{color:'#a16a19'}}>○ 1km</span><span>＋ 登録地点</span><span>市松＝取得済み透明（雨色なし） · 斜線＝未取得 · ほぼ白色も弱い雨</span></div>
 <details className={s.technical}><summary>詳しい判定理由・研究用の比較を見る</summary><section className={s.explanation}><h3>レーダーの不一致・判定不能の具体的な理由</h3><p className={s.notes}>画像の対象 {tokyo(selectedTime)}。時刻のずれは通知対象 {tokyo(evaluation.target_time)} を基準に確認します。レーダー上の差を表示します。現地報告は任意の参考情報であり、判定には使用しません。</p><p className={s.notes}>自動評価（雨色への遷移）：ぴったり {VERDICT_LABELS[evaluation.radar_result?.exact??'']??'未評価'} ／ ±5分 {VERDICT_LABELS[evaluation.radar_result?.within5??'']??'未評価'} ／ ±10分 {VERDICT_LABELS[evaluation.radar_result?.within10??'']??'未評価'}{evaluation.state==='PENDING'?'（処理中の暫定値）':''}</p>{explanations.length?<ul className={s.reasonList}>{explanations.map((x,i)=><li key={`${x.code}-${i}`} className={x.kind==='difference'?s.difference:s.hold}><strong>{x.kind==='difference'?'差あり':x.kind==='hold'?'保留':'比較の前提'}：{x.title}</strong><p>{x.detail}</p></li>)}</ul>:<p>この時刻の取得済みデータから、表示対象の不一致は検出されていません。地上の精度保証ではありません。</p>}</section>
 <div className={s.tableWrap}><table className={s.table}><thead><tr><th>方式</th><th>この時刻の候補</th><th>判定の根拠・保留理由</th></tr></thead><tbody>{METHODS.map(m=><tr key={m}><td className={s.method}>{METHOD_LABELS[m]}</td><td>{STATE_LABELS[candidates[m]?.state??'INDETERMINATE']}</td><td>{REASONS[candidates[m]?.reason??(m==='point'?'POINT_INPUT':'IMAGE_MISSING')]??'未確認'}</td></tr>)}</tbody></table></div>
 {[{name:'予測の面積内訳',feature},{name:'実況の面積内訳',feature:observationFeature}].map(({name,feature})=>feature?<div className={s.tableWrap} key={name}><table className={s.table}><caption>{name}</caption><thead><tr><th>範囲</th><th>雨域占有率</th><th>分類可能</th><th>欠測 / 未知色</th><th>中心の穴</th></tr></thead><tbody>{[250,500,1000].map(r=>{const c=feature.metrics.circles[String(r)];return c?<tr key={r}><td>{r===1000?'1km':`${r}m`}</td><td>{percent(c.rainFraction)}</td><td>{percent(c.usableCoverage)}</td><td>{percent(c.missingFraction)} / {percent(c.unknownFraction)}</td><td>{c.centerDryHoleM2===null?'—':`${Math.round(c.centerDryHoleM2).toLocaleString()}m²`}</td></tr>:null;})}</tbody></table></div>:<p className={s.notes} key={name}>{name}：画像の解析待ちです。</p>)}
 <p className={s.notes}>透明は取得できた画素で雨色がない状態です。未取得や、パレットにない未知色とは分けます。地上の無降雨を証明するものではありません。</p>
