.shell{min-height:100vh;background:#f2f5f8;color:#172c3d;font-family:system-ui,-apple-system,sans-serif;line-height:1.65;padding:28px 22px 70px;box-sizing:border-box}.wrap{max-width:1120px;margin:auto}.top{display:flex;justify-content:space-between;align-items:center;gap:16px}.top a{color:#315267;text-decoration:none}.eyebrow{font-size:12px;font-weight:800;letter-spacing:.14em;color:#27756e}.heading{font-size:clamp(27px,5vw,40px);line-height:1.3;letter-spacing:-.03em;margin:20px 0 9px}.muted{color:#526879;font-size:14px}.banner{background:#fff7e4;border:1px solid #e8d7a4;border-left:5px solid #b28b36;padding:16px 20px;border-radius:12px;margin:24px 0}.banner h2{font-size:19px;margin:0 0 5px}.banner p{margin:0;color:#6a562d;font-size:14px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:20px 0}.stat{background:#fff;border:1px solid #dce4eb;border-radius:14px;padding:18px 22px}.stat strong{display:block;font-size:32px;font-variant-numeric:tabular-nums}.stat span{font-size:13px;color:#526879}.panel{background:white;border:1px solid #dce4eb;border-radius:16px;padding:24px;margin:20px 0;box-shadow:0 4px 16px #21395404}.panel h2{font-size:21px;margin:0 0 12px}.panel h3{font-size:17px;margin:16px 0 8px}.filters{display:flex;gap:14px;flex-wrap:wrap;align-items:flex-end}.label{display:flex;flex-direction:column;gap:6px;font-size:13px;font-weight:700;min-width:130px}.shell select,.shell input,.shell textarea{font:inherit;font-size:16px;border:1px solid #b8c8d3;border-radius:9px;background:white;padding:9px 11px;color:#183447;max-width:100%;box-sizing:border-box}.shell button,.button{font:inherit;font-size:15px;font-weight:700;padding:10px 16px;border-radius:9px;border:1px solid #1c6a65;background:#1c6a65;color:white;cursor:pointer;text-decoration:none;display:inline-block}.shell button:disabled{opacity:.5;cursor:wait}.shell button:focus-visible,.shell a:focus-visible,.shell select:focus-visible,.shell input:focus-visible{outline:3px solid #65aaa6;outline-offset:3px}.tableWrap{overflow-x:auto}.table{border-collapse:collapse;width:100%;min-width:580px;font-size:14px}.table th{text-align:left;font-size:12px;color:#526879;font-weight:700;white-space:nowrap;border-bottom:1px solid #cfdce4;padding:12px 10px}.table td{padding:16px 10px;border-bottom:1px solid #e6edf1;font-variant-numeric:tabular-nums}.method{font-weight:750}.rate{font-size:22px;font-weight:800;color:#216b65}.empty{padding:30px 15px;background:#f7fafb;border:1px dashed #b8ccd6;border-radius:12px;color:#526879}.empty strong{display:block;color:#263f50;font-size:18px;margin-bottom:8px}.case{border:1px solid #dce4eb;border-radius:12px;margin:12px 0;overflow:hidden}.case summary{cursor:pointer;padding:17px;background:#f8fbfc;list-style:none;display:flex;justify-content:space-between;gap:12px}.case summary::after{content:'＋';color:#32746f}.case[open] summary::after{content:'−'}.caseBody{padding:18px}.tag{display:inline-block;font-size:12px;background:#e8f2f0;color:#285e59;border-radius:20px;padding:3px 10px;margin:3px 5px 3px 0}.tagWarn{background:#fff1d7;color:#755916}.images{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:16px 0}.figure{margin:0;min-width:0;background:#f7fafb;border:1px solid #dce4eb;border-radius:12px;padding:14px}.figure figcaption{font-weight:700;font-size:14px}.crop{position:relative;aspect-ratio:1;max-width:280px;width:100%;margin:12px auto;background-color:#f4f6f8;background-image:linear-gradient(45deg,#e1e6eb 25%,transparent 25%),linear-gradient(-45deg,#e1e6eb 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#e1e6eb 75%),linear-gradient(-45deg,transparent 75%,#e1e6eb 75%);background-size:16px 16px;background-position:0 0,0 8px,8px -8px,-8px 0}.crop img,.crop svg{position:absolute;inset:0;width:100%;height:100%}.crop img{image-rendering:pixelated}.legend{font-size:12px;display:flex;gap:12px;flex-wrap:wrap;color:#526879}.health{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.healthItem{border:1px solid #d